def translate(message, language="en"):
    """Return the localized catalog value, falling back to the English source."""
    translated = CATALOG.get(language, {}).get(message, message)
    if "{" in translated:
        try:
            translated = translated.format(**{key: key for key in ()})
        except (KeyError, ValueError):
            pass
    return translated
